CREATE POLICY "Users read own panel art" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'panels' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users upload own panel art" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'panels' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own panel art" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'panels' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'panels' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own panel art" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'panels' AND (storage.foldername(name))[1] = auth.uid()::text);